-- Check how many distinct robots exist in joint_condition vs operation
SELECT COUNT(DISTINCT jcdetref) as jc_robots, COUNT(DISTINCT operbotdetref) as op_robots
FROM joint_condition, operation;

-- Check how many distinct robots in robot_details and robot_record
SELECT COUNT(*) as rd_count, (SELECT COUNT(*) FROM robot_record) as rr_count
FROM robot_details;

-- Check all columns for any MJT reference
SELECT table_name, column_name FROM information_schema.columns 
WHERE column_name LIKE '%mj%' OR column_name LIKE '%max%';

