-- Check if any robots in joint_condition don't have operations
SELECT COUNT(*) FROM (
    SELECT DISTINCT jc.jcdetref 
    FROM joint_condition jc
    WHERE NOT EXISTS (SELECT 1 FROM operation o WHERE o.operbotdetref = jc.jcdetref)
) sub;
